//! Interoperability vectors for the RFC 3830 §4.1.2 PRF, produced by an
//! independent implementation.
//!
//! The expected values below were generated by compiling libmikey's own
//! `p()` and `prf()` — lifted verbatim from
//! `libmikey/keyagreement/KeyAgreement.cxx` lines 132-222 of csd/minisip at
//! commit 6f449fb — against OpenSSL, and running it on fixed inputs. See
//! `book/src/concepts/interop.md` for the harness and the full analysis.
//!
//! Only input-key lengths that are *not* an exact multiple of 32 bytes appear
//! here. At exact multiples libmikey discards the final 32-byte block of the
//! input key (it passes `inkeyLength % 32`, which is 0, as the block length),
//! so its output there is not a valid reference. `prf_is_key_sensitive_at_
//! multiples_of_32` pins down the behaviour mykey implements instead.

use mykey::crypto::{
    mikey_prf, CONST_AUTH_FROM_PSK, CONST_AUTH_FROM_TGK, CONST_ENC_FROM_PSK, CONST_ENC_FROM_TGK,
    CONST_SALT_FROM_PSK, CONST_SALT_FROM_TGK, CONST_TEK,
};

/// label = 4-byte constant || cs_id || csb_id (big endian) || RAND,
/// per RFC 3830 §4.1.3-§4.1.4 and libmikey's `KeyAgreement::keyDeriv`.
fn label(constant: u32, cs_id: u8, csb_id: u32, rand: &[u8]) -> Vec<u8> {
    let mut l = Vec::with_capacity(9 + rand.len());
    l.extend_from_slice(&constant.to_be_bytes());
    l.push(cs_id);
    l.extend_from_slice(&csb_id.to_be_bytes());
    l.extend_from_slice(rand);
    l
}

/// The same deterministic input libmikey's harness was given.
fn inkey() -> Vec<u8> {
    (0..128u32).map(|i| (i * 7 + 1) as u8).collect()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

const RAND: [u8; 16] = [0x5A; 16];

