#[test]
fn prf_matches_libmikey() {
    let inkey = inkey();
    let l = label(CONST_TEK, 0x00, 0x1234_5678, &RAND);
    for &(inlen, outlen, expected) in LIBMIKEY_PRF {
        let got = mikey_prf(&inkey[..inlen], &l, outlen).expect("prf");
        assert_eq!(
            hex(&got),
            expected,
            "PRF mismatch vs libmikey at inlen={inlen} outlen={outlen}"
        );
    }
}

/// Full key derivation for all seven RFC 3830 constants, as computed by libmikey.
const LIBMIKEY_DERIV: &[(u32, u8, usize, &str)] = &[
    (
        CONST_SALT_FROM_TGK,
        0x00,
        16,
        "008d178daeaba844e1cd9ae091685cad3cfcec69",
    ),
    (
        CONST_TEK,
        0x00,
        16,
        "0fcd76773dc64e23b17fe67580fe35f227b9eae5",
    ),
    (
        CONST_ENC_FROM_PSK,
        0xFF,
        16,
        "952af58f41e8ef1ea73605eeca717eba355dacff",
    ),
    (
        CONST_SALT_FROM_PSK,
        0xFF,
        16,
        "be7d4e6d7faef61bf9396378fca947c078120a92",
    ),
    (
        CONST_AUTH_FROM_PSK,
        0xFF,
        16,
        "04c9c96c24779336d03ad6dafd366d826353f9de",
    ),
    (
        CONST_ENC_FROM_TGK,
        0x00,
        16,
        "bab2c45a15bf4b5f195da424bc192c4573c512a1",
    ),
    (
        CONST_AUTH_FROM_TGK,
        0x00,
        16,
        "20e10614bf4a778bcfcb90d36025ba684ff07c77",
    ),
];

#[test]
fn key_derivation_matches_libmikey() {
    let inkey = inkey();
    for &(constant, cs_id, inlen, expected) in LIBMIKEY_DERIV {
        let l = label(constant, cs_id, 0x1234_5678, &RAND);
        let got = mikey_prf(&inkey[..inlen], &l, 20).expect("prf");
        assert_eq!(
            hex(&got),
            expected,
            "derivation mismatch vs libmikey for constant {constant:#010x} \
             cs_id={cs_id:#04x} inlen={inlen}"
        );
    }
}

/// RFC 3830 §4.1.2 splits `inkey` into `n = ceil(inkey_len / 256 bits)` blocks
/// where "all s_i, except possibly s_n, are 256 bits each" — so a 32-byte key
/// is one full 256-bit block and must be used in its entirety.
///
/// libmikey instead passes `inkeyLength % 32` as the final block length, which
/// is 0 at exact multiples, making it HMAC with an empty key. At `inkey_len ==
/// 32` that degenerate call is the only one, so libmikey's derived keys there
/// depend solely on the label — public wire data. This test pins the property
/// libmikey loses: the output must depend on the key.
#[test]
fn prf_is_key_sensitive_at_multiples_of_32() {
    let l = label(CONST_TEK, 0x00, 0x1234_5678, &RAND);

    for len in [32usize, 64, 96, 128] {
        let a: Vec<u8> = (0..len).map(|i| (i * 31 + 7) as u8).collect();
        let b: Vec<u8> = (0..len).map(|i| (i * 131 + 200) as u8).collect();
        assert_ne!(
            mikey_prf(&a, &l, 20).unwrap(),
            mikey_prf(&b, &l, 20).unwrap(),
            "PRF output must depend on the input key at inkey_len={len}"
        );

        // Mutating only the final 32-byte block must change the output; this is
        // exactly the block libmikey drops.
        let mut c = a.clone();
        for byte in &mut c[len - 32..] {
            *byte ^= 0xFF;
        }
        assert_ne!(
            mikey_prf(&a, &l, 20).unwrap(),
            mikey_prf(&c, &l, 20).unwrap(),
            "final 32-byte block of the input key must affect the output at \
             inkey_len={len}"
        );
    }
}
